+
+function activeValues(
+  storage: AccountV2Storage,
+): LocalProfileArchiveV1['values'] {
+  const values: LocalProfileArchiveV1['values'] = {};
+  for (const key of ACCOUNT_BOUNDARY_PROFILE_KEYS) {
+    const value = storage.getItem(key);
